import heapq
E = {('S','A'):3,('S','B'):2,('A','B'):2,('A','C'):6,('B','C'):3,('B','D'):6,
     ('C','E'):2,('C','T'):6,('D','E'):8,('D','T'):2,('E','T'):3}
def dijkstra(E):
    g = {}
    for (u, v), w in E.items(): g.setdefault(u, []).append((v, w))
    dist, order, pq = {'S': 0}, [], [(0, 'S')]
    while pq:
        d, u = heapq.heappop(pq)
        if u in order: continue
        order.append(u)
        for v, w in g.get(u, []):
            if d + w < dist.get(v, 1e9): dist[v] = d + w; heapq.heappush(pq, (d + w, v))
    return dist, order
def costs(u, c, E, out):                      # the graph is a DAG, so plain recursion enumerates all paths
    if u == 'T': out.append(c)
    for (a, b), w in E.items():
        if a == u: costs(b, c + w, E, out)
dist, order = dijkstra(E)
