def joins(fk, needed):
    parent = {c: p for p, cs in fk.items() for c in cs}
    used = {'CallFact'}
    for t in needed:                                                       # walk each needed table back to the fact table
        while t not in used:
            used.add(t); t = parent[t]
    return len(used) - 1
